 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, color, texture } from 'three/tsl';
import { gsap } from 'gsap';
import * as TextFonts from '@/text';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  const visual = config.intent?.visualSpec ?? config.visual ?? {};
  const palette = visual.colors ?? config.colors ?? {};
  const typography = visual.typography ?? config.typography ?? {};
  const items = config.textContent ?? visual.textContent ?? [];
  const primitives = config.cinematicPrimitives ?? [];

  const bgHex = palette.background ?? '#0b0b10';
  const surfaceHex = palette.surface ?? '#14141a';
  const accentHex = palette.accent ?? '#ff2a38';
  const paperHex = palette.paper ?? '#e8ecf2';
  const inkHex = palette.ink ?? '#16161d';

  const root = new THREE.Group();

  // --- helpers ---
  function collectMaterials(obj, list) {
    obj.traverse((child) => {
      if (child.material) {
        const mats = Array.isArray(child.material) ? child.material : [child.material];
        mats.forEach((m) => {
          m.transparent = true;
          m.needsUpdate = true;
          list.push(m);
        });
      }
    });
  }

  function setOpacity(list, v) {
    list.forEach((m) => { m.opacity = v; });
  }

  // --- backdrop plate: vertical gradient + 1.5% monochrome grain ---
  const noiseData = new Uint8Array(256 * 256);
  for (let i = 0; i < noiseData.length; i++) noiseData[i] = Math.floor(Math.random() * 256);
  const noiseTex = new THREE.DataTexture(noiseData, 256, 256, THREE.RedFormat);
  noiseTex.wrapS = THREE.RepeatWrapping;
  noiseTex.wrapT = THREE.RepeatWrapping;
  noiseTex.needsUpdate = true;

  const gradT = uv().y;
  const gradient = mix(color(surfaceHex), color(bgHex), gradT);
  const grainUV = uv().mul(vec2(512, 512));
  const grainSample = texture(noiseTex, grainUV);
  const grain = grainSample.sub(0.5).mul(0.015).xxx;
  const plateColor = gradient.add(grain);

  const plate = new THREE.Mesh(
    new THREE.PlaneGeometry(7, 5.5),
    new MeshBasicNodeMaterial({ colorNode: plateColor })
  );
  root.add(plate);

  // --- accent rule ---
  const ruleWrap = new THREE.Group();
  ruleWrap.position.set(-3.1, -0.15, 0.05);
  const ruleGeo = new THREE.PlaneGeometry(2.2, 0.05);
  ruleGeo.translate(1.1, 0, 0);
  const ruleMat = new MeshBasicNodeMaterial({ colorNode: color(accentHex).mul(1.2) });
  const rule = new THREE.Mesh(ruleGeo, ruleMat);
  ruleWrap.scale.x = 0;
  ruleWrap.add(rule);
  root.add(ruleWrap);

  // --- text sizing ---
  const heroSize = 0.62;
  const scaleFactor = heroSize / (typography.hero?.fontSize ?? 124);

  function pxSize(role) {
    return (typography[role]?.fontSize ?? 18) * scaleFactor;
  }

  function makeTextOpts(item, role) {
    const px = typography[role]?.fontSize ?? 18;
    const size = px * scaleFactor;
    const tracking = item.typography?.letterSpacing ?? typography[role]?.letterSpacing ?? 0;
    const weight = item.typography?.fontWeight ?? typography[role]?.fontWeight ?? 400;

    const roleFamily =
      role === 'hero' ? 'Lora' :
      role === 'kicker' ? 'JetBrains Mono' :
      role === 'body' ? 'JetBrains Mono' :
      role === 'caption' ? 'JetBrains Mono' : 'JetBrains Mono';

    const fontObj = role === 'hero' ? TextFonts.Lora : TextFonts.JetBrainsMono;

    const opts = {
      fontSize: size,
      color: paperHex,
      align: 'left',
      letterSpacingPx: size * tracking,
      fontWeight: weight,
      fontFamily: roleFamily,
      font: fontObj,
    };

    if (role === 'body') {
      opts.maxWidthPx = 4.5;
    }

    return opts;
  }

  // --- build and animate blocks ---
  const tl = gsap.timeline();
  const primitiveRuns = [];
  const allTextMeshes = [];
  const allMaterials = [];

  function addBlock(item, y, startAt) {
    if (!item) return;
    const role = item.role ?? 'body';
    const wrap = new THREE.Group();
    wrap.position.set(-3.1, y + 0.4, 0.05);

    const opts = makeTextOpts(item, role);
    const text = ctx.fontAtlas.createText(item.text, opts);
    wrap.add(text);

    if (role === 'hero') {
      const shadow = ctx.fontAtlas.createText(item.text, { ...opts, color: inkHex });
      shadow.position.z = -0.02;
      wrap.add(shadow);
    }

    const mats = [];
    collectMaterials(wrap, mats);
    allMaterials.push(...mats);
    allTextMeshes.push(wrap);
    root.add(wrap);

    setOpacity(mats, 0);

    const proxy = { value: 0 };
    tl.to(wrap.position, { y, duration: 0.7, ease: 'power3.out' }, startAt);
    tl.to(
      proxy,
      {
        value: 1,
        duration: 0.7,
        ease: 'power3.out',
        onUpdate: () => setOpacity(mats, proxy.value),
      },
      startAt
    );
  }

  const kickerItem = items.find((i) => i.role === 'kicker');
  const heroItems = items.filter((i) => i.role === 'hero');
  const bodyItem = items.find((i) => i.role === 'body');
  const captionItem = items.find((i) => i.role === 'caption');

  if (kickerItem) addBlock(kickerItem, 1.7, 0.0);
  heroItems.slice(0, 2).forEach((it, idx) => addBlock(it, idx === 0 ? 0.9 : 0.25, 0.08 + idx * 0.08));

  const ruleStart = 0.86;
  tl.to(ruleWrap.scale, { x: 1, duration: 0.5, ease: 'power2.out' }, ruleStart);

  const bodyStart = ruleStart + 0.08;
  const captionStart = bodyStart + 0.08;
  if (bodyItem) addBlock(bodyItem, -0.8, bodyStart);
  if (captionItem) addBlock(captionItem, -1.9, captionStart);

  // --- cinematic primitives ---
  primitives.forEach((p) => {
    if (ctx.primitives[p.name]) {
      primitiveRuns.push(ctx.primitives[p.name](root, p.params ?? {}));
    }
  });

  // --- userData ---
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    primitiveRuns.forEach((r) => {
      if (r && typeof r.cleanup === 'function') r.cleanup();
    });

    const disposeObj = (obj) => {
      obj.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      });
    };

    disposeObj(ruleWrap);
    allTextMeshes.forEach(disposeObj);
    disposeObj(root);
    noiseTex.dispose();
  };

  return root;
}
